begin;
-- Extend style enums without adding experimental items to any loot pool.
do $$ declare row record; extra_styles text[]:=array['lab-blue-4-rose-quartz','lab-blue-4-polar-amber','lab-blue-4-tourmaline','lab-blue-4-glacial-opal','lab-blue-4-garnet','lab-blue-4-vivid-topaz','lab-blue-4-obsidian','lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-golden-mirage','lab-blue-6-crimson-silk','lab-blue-6-moonlight','lab-blue-7-acid-pulse','lab-blue-7-ruby-laser','lab-blue-7-lilac-code','lab-blue-7-solar-pixel','lab-blue-7-turquoise-beat','lab-blue-7-pink-tuning','lab-blue-7-white-signal','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity','lab-blue-9-meteorite','lab-blue-9-amber-cosmos','lab-blue-9-crimson-star','lab-blue-10-red-aurora','lab-blue-10-jade-sky','lab-blue-10-borealis','lab-blue-10-pink-horizon','lab-blue-10-tropical-light','lab-blue-10-indigo-vortex','lab-blue-10-golden-galaxy']; col text;
begin
 for row in select conname,pg_get_constraintdef(oid) definition from pg_constraint where conrelid='public.public_profiles'::regclass and conname in ('pass_name_style_check','pass_border_style_check') loop
  col:=case when row.conname='pass_name_style_check' then 'pass_name_style' else 'pass_border_style' end;
  execute format('alter table public.public_profiles drop constraint %I',row.conname);
  execute format('alter table public.public_profiles add constraint %I check ((%s) or (player_id=1000001 and %I=any(%L::text[])))',row.conname,substring(row.definition from 8 for length(row.definition)-8),col,extra_styles);
 end loop;
end; $$;
alter table public.public_profiles drop constraint active_blue_name_styles;
alter table public.public_profiles drop constraint active_blue_frame_styles;
alter table public.public_profiles add constraint active_blue_name_styles check(left(pass_name_style,9)<>'lab-blue-' or (player_id=1000001 and pass_name_style in ('lab-blue-4','lab-blue-6','lab-blue-7','lab-blue-9','lab-blue-10','lab-blue-4-rose-quartz','lab-blue-4-polar-amber','lab-blue-4-tourmaline','lab-blue-4-glacial-opal','lab-blue-4-garnet','lab-blue-4-vivid-topaz','lab-blue-4-obsidian','lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-golden-mirage','lab-blue-6-crimson-silk','lab-blue-6-moonlight','lab-blue-7-acid-pulse','lab-blue-7-ruby-laser','lab-blue-7-lilac-code','lab-blue-7-solar-pixel','lab-blue-7-turquoise-beat','lab-blue-7-pink-tuning','lab-blue-7-white-signal','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity','lab-blue-9-meteorite','lab-blue-9-amber-cosmos','lab-blue-9-crimson-star','lab-blue-10-red-aurora','lab-blue-10-jade-sky','lab-blue-10-borealis','lab-blue-10-pink-horizon','lab-blue-10-tropical-light','lab-blue-10-indigo-vortex','lab-blue-10-golden-galaxy')));
alter table public.public_profiles add constraint active_blue_frame_styles check(left(pass_border_style,9)<>'lab-blue-' or (player_id=1000001 and pass_border_style in ('lab-blue-4','lab-blue-6','lab-blue-7','lab-blue-9','lab-blue-10','lab-blue-4-rose-quartz','lab-blue-4-polar-amber','lab-blue-4-tourmaline','lab-blue-4-glacial-opal','lab-blue-4-garnet','lab-blue-4-vivid-topaz','lab-blue-4-obsidian','lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-golden-mirage','lab-blue-6-crimson-silk','lab-blue-6-moonlight','lab-blue-7-acid-pulse','lab-blue-7-ruby-laser','lab-blue-7-lilac-code','lab-blue-7-solar-pixel','lab-blue-7-turquoise-beat','lab-blue-7-pink-tuning','lab-blue-7-white-signal','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity','lab-blue-9-meteorite','lab-blue-9-amber-cosmos','lab-blue-9-crimson-star','lab-blue-10-red-aurora','lab-blue-10-jade-sky','lab-blue-10-borealis','lab-blue-10-pink-horizon','lab-blue-10-tropical-light','lab-blue-10-indigo-vortex','lab-blue-10-golden-galaxy')));
create or replace function public.box_style_allowed(p_profile_id uuid,p_kind text,p_style text)
returns boolean language sql stable security definer set search_path=public,auth,pg_temp as $$
 select case when left(p_style,9)='lab-blue-' then
  p_kind in ('name','frame') and p_style in ('lab-blue-4','lab-blue-6','lab-blue-7','lab-blue-9','lab-blue-10','lab-blue-4-rose-quartz','lab-blue-4-polar-amber','lab-blue-4-tourmaline','lab-blue-4-glacial-opal','lab-blue-4-garnet','lab-blue-4-vivid-topaz','lab-blue-4-obsidian','lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-golden-mirage','lab-blue-6-crimson-silk','lab-blue-6-moonlight','lab-blue-7-acid-pulse','lab-blue-7-ruby-laser','lab-blue-7-lilac-code','lab-blue-7-solar-pixel','lab-blue-7-turquoise-beat','lab-blue-7-pink-tuning','lab-blue-7-white-signal','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity','lab-blue-9-meteorite','lab-blue-9-amber-cosmos','lab-blue-9-crimson-star','lab-blue-10-red-aurora','lab-blue-10-jade-sky','lab-blue-10-borealis','lab-blue-10-pink-horizon','lab-blue-10-tropical-light','lab-blue-10-indigo-vortex','lab-blue-10-golden-galaxy') and exists(select 1 from public.public_profiles where id=p_profile_id and player_id=1000001)
 else p_style='none' or (p_style<>'orange' and left(p_style,8)<>'preview-' and (
  exists(select 1 from public.public_profiles where id=p_profile_id and player_id=1000001)
  or exists(select 1 from public.box_inventory where profile_id=p_profile_id and kind=p_kind and style=p_style)
 )) end;
$$;
notify pgrst,'reload schema';
commit;
